items = [
    (1, "A1", "B1"),
    (1, "A1", "B2"),
    (1, "A2", "B1"),
    (-1, "A2", "B2")
]
expanded = []
for t1 in items:
    for t2 in items:
        s = t1[0] * t2[0]
        expanded.append((s, t1[1], t2[1], t1[2], t2[2]))

d = {}
for s, a1, a2, b1, b2 in expanded:
    a_str = "I" if a1 == a2 else f"{a1}{a2}"
    b_str = "I" if b1 == b2 else f"{b1}{b2}"
    pair = (a_str, b_str)
    d[pair] = d.get(pair, 0) + s

for k, v in d.items():
    print(f"{k}: {v}")

